SELECT s.browser, SUM(CASE WHEN we.event_type = 'page_view' THEN we.duration_sec ELSE 0 END) AS page_view_duration_sec, COUNT(we.duration_sec) AS duration_sec_count FROM web_events we LEFT JOIN sessions s ON we.session_id = s.id FULL OUTER JOIN customers c ON c.id = s.customer_id WHERE c.country IN ('SG', 'UK', 'TH') GROUP BY s.browser ORDER BY duration_sec_count DESC, page_view_duration_sec
